import{af as t,z as a,J as o,ab as i}from"./chunks/framework.BnTFvF69.js";const p=JSON.parse('{"title":"Devices","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"faq/devices.md","filePath":"faq/devices.md"}'),r={name:"faq/devices.md"};function s(h,e,l,n,d,c){return a(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793279959000"},[...e[0]||(e[0]=[i('<h1 id="devices" tabindex="-1">Devices <a class="header-anchor" href="#devices" aria-label="Permalink to &quot;Devices&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#can-the-devices-be-turned-off">Can the devices be turned off? ​</a></li><li><a href="#how-long-will-the-battery-last">How long will the battery last? ​</a></li><li><a href="#can-the-devices-operate-in-extreme-weather-conditions">Can the devices operate in extreme weather conditions? ​</a></li><li><a href="#are-the-devices-waterproof">Are the devices waterproof? ​</a></li><li><a href="#does-lightbug-install-the-devices">Does Lightbug install the devices? ​</a></li><li><a href="#will-the-devices-work-straight-out-of-the-box">Will the devices work straight out of the box? ​</a></li><li><a href="#what-comes-in-the-box">What comes in the box? ​</a></li><li><a href="#are-you-able-to-produce-custom-devices">Are you able to produce custom devices? ​</a></li><li><a href="#how-often-will-i-have-to-replace-a-lightbug-device">How often will I have to replace a Lightbug device? ​</a></li><li><a href="#where-is-the-best-place-to-mount-devices">Where is the best place to mount devices? ​</a></li><li><a href="#do-the-trackers-need-to-be-exposed">Do the trackers need to be exposed? ​</a></li><li><a href="#how-strong-is-the-pro-magnetic-mount">How strong is the Pro magnetic mount? ​</a></li></ul></nav><h2 id="can-the-devices-be-turned-off" tabindex="-1">Can the devices be turned off? <a class="header-anchor" href="#can-the-devices-be-turned-off" aria-label="Permalink to &quot;Can the devices be turned off?&quot;">​</a></h2><p>There is no physical on/off button on any of our trackers, but you can disable the device through the <a href="/docs/pr/30/apps/cloud/">Lightbug App</a>.</p><p>If you no longer need the device, you can cancel your subscription at any time and reactivate devices at a later date.</p><p>There are other forms of control accessible via APIs, such as the ability to lock the device in sleep mode for up to 24 hours, which will temporarily disable location updates when moving. Or the ability to put a device in deep sleep, there is will need to be put on charge or button pressed to wake it up.</p><h2 id="how-long-will-the-battery-last" tabindex="-1">How long will the battery last? <img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/107HL9y.png" alt="" width="100" style="float:right;"> <a class="header-anchor" href="#how-long-will-the-battery-last" aria-label="Permalink to &quot;How long will the battery last? ![](https://upload.r2.lb.chasm.cloud/2025/10/imgur/107HL9y.png){width=100 style=&quot;float:right&quot;}&quot;">​</a></h2><p>The battery life of the device depends on your required settings.</p><p>The best way to find out the estimated battery life is to use our <a href="https://lightbug.io/" target="_blank" rel="noreferrer">battery life calculator</a> on our website.</p><h2 id="can-the-devices-operate-in-extreme-weather-conditions" tabindex="-1">Can the devices operate in extreme weather conditions? <a class="header-anchor" href="#can-the-devices-operate-in-extreme-weather-conditions" aria-label="Permalink to &quot;Can the devices operate in extreme weather conditions?&quot;">​</a></h2><p>Device operating temperature differs between different models and versions, so the device specification should be checked. All current core devices operate between 0°C to 50°C, if you have other requirements this can be customized. In both the extremely higher and lower temperatures the battery life of devices may be affected.</p><h2 id="are-the-devices-waterproof" tabindex="-1">Are the devices waterproof? <a class="header-anchor" href="#are-the-devices-waterproof" aria-label="Permalink to &quot;Are the devices waterproof?&quot;">​</a></h2><p>Check the device specifications on the <a href="/docs/pr/30/devices">dedicated device pages</a> for the IP rating of the device.</p><h2 id="does-lightbug-install-the-devices" tabindex="-1">Does Lightbug install the devices? <a class="header-anchor" href="#does-lightbug-install-the-devices" aria-label="Permalink to &quot;Does Lightbug install the devices?&quot;">​</a></h2><p>No, we do not install devices.</p><p>Some devices, such as the vehicle tracker, have <a href="/docs/pr/30/devices/vehicle/installation">dedicated installation guides</a>.</p><p>Should you have any questions on installation and mounting, we&#39;re happy to help!</p><h2 id="will-the-devices-work-straight-out-of-the-box" tabindex="-1">Will the devices work straight out of the box? <a class="header-anchor" href="#will-the-devices-work-straight-out-of-the-box" aria-label="Permalink to &quot;Will the devices work straight out of the box?&quot;">​</a></h2><p>The devices arrive <strong>ready to use</strong>, there is no assembly required; however, you will need to charge and activate your tracker.</p><p>You&#39;ll possibly find the <a href="/docs/pr/30/guides/adding-your-first-device">adding my first device guide</a> useful if this is your first time using a Lightbug device.</p><h2 id="what-comes-in-the-box" tabindex="-1">What comes in the box? <img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/CaCDdWV.png" alt="" width="220" style="float:right;"> <a class="header-anchor" href="#what-comes-in-the-box" aria-label="Permalink to &quot;What comes in the box? ![](https://upload.r2.lb.chasm.cloud/2025/10/imgur/CaCDdWV.png){width=220 style=&quot;float:right&quot;}&quot;">​</a></h2><p>The contents of the box will vary depending on the device you have ordered.</p><p>The lightbug.io product listings include all information on what is bundled with the various SKUs.</p><p>Such as the page for the <a href="https://lightbug.io/product/lb-dev-pr2/" target="_blank" rel="noreferrer">Pro</a> which at the time of writing includes the Pro device, a charge dock, USB cable and one month of data.</p><h2 id="are-you-able-to-produce-custom-devices" tabindex="-1">Are you able to produce custom devices? <a class="header-anchor" href="#are-you-able-to-produce-custom-devices" aria-label="Permalink to &quot;Are you able to produce custom devices?&quot;">​</a></h2><p>Yes we can, we love being surprised by the new and innovative uses for our tracking technology!</p><p>So, if our devices don’t exactly fit your requirements, get in touch and we’ll see what we can do.</p><p>See <a href="/docs/pr/30/devices/custom">the custom devices page</a> for more information.</p><h2 id="how-often-will-i-have-to-replace-a-lightbug-device" tabindex="-1">How often will I have to replace a Lightbug device? <a class="header-anchor" href="#how-often-will-i-have-to-replace-a-lightbug-device" aria-label="Permalink to &quot;How often will I have to replace a Lightbug device?&quot;">​</a></h2><p>Unless there is accidental damage, you should not need to replace your Lightbug GPS tracker.</p><p>If your device has a manufacturing defect within the first three years, it is likely covered under warranty, please <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">contact us</a>, as this differs per device and manufacture date.</p><h2 id="where-is-the-best-place-to-mount-devices" tabindex="-1">Where is the best place to mount devices? <a class="header-anchor" href="#where-is-the-best-place-to-mount-devices" aria-label="Permalink to &quot;Where is the best place to mount devices?&quot;">​</a></h2><p>It depends on your use case.</p><p>However, please do not fully surround the tracker with metal as it blocks the signals.</p><p>Below are some recommendations for best performance, if none of the suggestions work well for you, get in touch with details of your use case.</p><p>Some suggestions:</p><ul><li>People: a bag, shoes, outside pocket, keys, lanyard</li><li>Assets: face the device upwards with a clear line of sight to the sky</li><li>Vehicle: glove compartment, under the seat, underside of the vehicle (magnetic LightBug Pro)</li></ul><h2 id="do-the-trackers-need-to-be-exposed" tabindex="-1">Do the trackers need to be exposed? <a class="header-anchor" href="#do-the-trackers-need-to-be-exposed" aria-label="Permalink to &quot;Do the trackers need to be exposed?&quot;">​</a></h2><p>Our trackers do not need to be fully exposed; however, they do not work well when fully surrounded by metal as this blocks the signals.</p><h2 id="how-strong-is-the-pro-magnetic-mount" tabindex="-1">How strong is the Pro magnetic mount? <a class="header-anchor" href="#how-strong-is-the-pro-magnetic-mount" aria-label="Permalink to &quot;How strong is the Pro magnetic mount?&quot;">​</a></h2><p>The magnet is powerful with a pull force of 70lb / 32kg.</p><p>It will securely mount the Lightbug Pro to the underside of a moving vehicle.</p>',42)])])}const f=t(r,[["render",s]]);export{p as __pageData,f as default};
